import React from "react";

import "../assets/css/loading-page.css";

function LoadingPage(props) {
  let x = 100;
  let y = 100;

  let radius = 100;
  return (
    <div className="loading-page-wrapper">
      <h1 className="loading-text-wrapper montserrat-light">loading</h1>
      <div
        className="circle"
        style={{
          offsetPath: `path("M ${startingPositions[0].x - radius}, ${
            startingPositions[0].y
          } a ${radius},${radius} 0 1,0 ${
            radius * 2
          },0 a ${radius},${radius} 0 1,0 -${radius * 2},0")`
        }}
      ></div>
      <div
        className="circle"
        style={{
          offsetPath: `path("M ${startingPositions[1].x + radius}, ${
            startingPositions[1].y
          } a ${radius},${radius} 0 1,0 ${
            radius * 2
          },0 a ${radius},${radius} 0 1,0 -${radius * 2},0")`
        }}
      ></div>
      <div
        className="circle"
        style={{
          offsetPath: `path("M ${startingPositions[2].x}, ${
            startingPositions[2].y + radius
          } a ${radius},${radius} 0 1,0 ${
            radius * 2
          },0 a ${radius},${radius} 0 1,0 -${radius * 2},0")`
        }}
      ></div>
      <div
        className="circle"
        style={{
          offsetPath: `path("M ${startingPositions[3].x - radius}, ${
            startingPositions[3].y - radius
          } a ${radius},${radius} 0 1,0 ${
            radius * 2
          },0 a ${radius},${radius} 0 1,0 -${radius * 2},0")`
        }}
      ></div>
    </div>
  );
}

export default LoadingPage;
